manifest=[]
def asset(relative):
 src=base/relative;assert src.exists(),str(src);dst=assets/src.name
 shutil.copy2(src,dst)
 file='assets/'+dst.name
 if not any(m['file']==file for m in manifest):manifest.append({'file':file,'sha256':hashlib.sha256(dst.read_bytes()).hexdigest(),'origin':relative})
